CREATE OR REPLACE FUNCTION public.is_payment_request_approver_for_company(p_profile_id uuid, p_company_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select cardinality(
    private.profile_company_approver_roles(p_profile_id, p_company_id)
  ) > 0;
$function$

CREATE OR REPLACE FUNCTION public.validate_payment_request_approver_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment public.approver_assignments%rowtype;
  v_assignment_changed boolean;
  v_legacy_assignment_snapshot boolean := false;
begin
  if new.approver_id is null then
    if tg_op = 'INSERT' then
      raise exception 'payment_request_approver_required';
    end if;
    if old.approver_id is not null
       or new.company_id is distinct from old.company_id
       or new.requested_by is distinct from old.requested_by then
      raise exception 'payment_request_approver_required';
    end if;
    return new;
  end if;

  if new.requested_by is null then
    raise exception 'payment_request_requester_required';
  end if;
  if new.requested_by = new.approver_id then
    raise exception 'requester_cannot_be_own_approver';
  end if;
  if tg_op = 'UPDATE' and (
    new.approver_id is distinct from old.approver_id
    or new.approver_assignment_id is distinct from old.approver_assignment_id
    or new.approver_selection_source is distinct from old.approver_selection_source
  ) then
    raise exception 'payment_request_approver_selection_immutable';
  end if;
  v_assignment_changed := tg_op = 'INSERT';
  if tg_op = 'UPDATE' then
    v_assignment_changed := new.approver_assignment_id is distinct from old.approver_assignment_id;
  end if;

  if new.approver_assignment_id is not null then
    if new.approver_selection_source is distinct from 'assigned' then
      raise exception 'approver_assignment_source_mismatch';
    end if;
    select * into v_assignment
    from public.approver_assignments aa
    where aa.id = new.approver_assignment_id;

    if not found
       or v_assignment.company_id <> new.company_id
       or v_assignment.requester_id <> new.requested_by
       or v_assignment.approver_id <> new.approver_id then
      raise exception 'approver_assignment_snapshot_mismatch';
    end if;
    if v_assignment_changed and not v_assignment.active then
      raise exception 'approver_assignment_not_active';
    end if;
    if v_assignment_changed then
      if not public.has_active_company_membership(new.requested_by, new.company_id) then
        raise exception 'requester_company_membership_required';
      end if;
      if not public.is_payment_request_approver_for_company(new.approver_id, new.company_id) then
        raise exception 'approver_not_eligible_for_company';
      end if;
    end if;
  else
    if new.approver_selection_source = 'assigned' then
      raise exception 'approver_assignment_id_required';
    end if;
    if tg_op = 'INSERT' and new.approver_selection_source is distinct from 'approval_rules' then
      raise exception 'approver_selection_source_required';
    end if;
    if new.approver_selection_source = 'approval_rules'
       and public.payment_request_has_active_approver_pool(new.requested_by, new.company_id) then
      raise exception 'approver_must_come_from_configured_pool';
    end if;

    -- Migration 018 stored only approver_id. If the same assignment already
    -- existed when the request was created, preserve that historical snapshot
    -- when other editable request fields change.
    if tg_op = 'UPDATE'
       and new.approver_selection_source is null
       and new.company_id is not distinct from old.company_id
       and new.requested_by is not distinct from old.requested_by then
      select exists (
        select 1
        from public.approver_assignments aa
        where aa.company_id = new.company_id
          and aa.requester_id = new.requested_by
          and aa.approver_id = new.approver_id
          and aa.created_at <= old.created_at
      ) into v_legacy_assignment_snapshot;
    end if;

    if not v_legacy_assignment_snapshot then
      if not public.has_active_company_membership(new.requested_by, new.company_id) then
        raise exception 'requester_company_membership_required';
      end if;
      if not public.is_payment_request_approver_for_company(new.approver_id, new.company_id) then
        raise exception 'approver_not_eligible_for_company';
      end if;
      if not public.payment_request_rule_allows(
        new.approver_id,
        new.company_id,
        new.cost_center_id,
        new.amount_requested,
        'approved'
      ) then
        raise exception 'approver_not_allowed_by_approval_rules';
      end if;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_payment_request_number(p_year integer DEFAULT (EXTRACT(year FROM now()))::integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$

declare

  v_next bigint;

begin

  v_next := nextval('public.payment_request_number_seq');



  return 'SOL-' || p_year::text || '-' || lpad(v_next::text, 4, '0');

end;

$function$

CREATE OR REPLACE FUNCTION public.set_payment_request_no_presupuestal_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_no_presupuestal boolean;
begin
  if tg_op = 'UPDATE'
     and new.budget_category_id is not distinct from old.budget_category_id then
    if new.no_presupuestal is distinct from old.no_presupuestal then
      raise exception 'no_presupuestal_snapshot_immutable';
    end if;
    return new;
  end if;

  select coalesce(category.no_presupuestal, false)
    into v_no_presupuestal
  from public.budget_categories category
  where category.id = new.budget_category_id;

  new.no_presupuestal := coalesce(v_no_presupuestal, false);
  if new.no_presupuestal then
    new.budget_decision := 'aprobable';
    new.budget_block_reason := 'no_presupuestal';
    new.budget_available_before := null;
    new.budget_available_after := null;
    new.budget_shortfall := 0;
    new.budget_checked_at := now();
    new.budget_result := jsonb_build_object(
      'status', 'aprobable',
      'motivo', 'no_presupuestal',
      'disponible_actual', null,
      'disponible_despues', null,
      'faltante', 0,
      'no_presupuestal', true
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_payment_request_created_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_role_name text;
  v_status text := 'pending';
  v_last_error text;
  v_payload jsonb;
begin
  if new.approver_id is null then
    v_status := 'dead_letter';
    v_last_error := 'missing_approver_profile_id';
  else
    select * into v_profile
    from public.profiles
    where id = new.approver_id and coalesce(active, true);

    if not found then
      v_status := 'dead_letter';
      v_last_error := 'approver_profile_not_found';
    elsif not public.is_payment_request_approver_for_company(new.approver_id, new.company_id) then
      v_status := 'dead_letter';
      v_last_error := 'approver_not_eligible_for_company';
    elsif nullif(btrim(coalesce(v_profile.email, '')), '') is null then
      v_status := 'no_recipient';
      v_last_error := 'recipient_email_missing';
    end if;
  end if;

  select lower(trim(r.name)) into v_role_name
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  where ur.profile_id = new.approver_id
    and lower(trim(r.name)) = any (public.payment_request_approver_role_names())
  order by lower(trim(r.name))
  limit 1;

  v_payload := public.notification_payment_request_payload_with_extra(
    new.id,
    jsonb_build_object(
      'approver', coalesce(nullif(btrim(v_profile.full_name), ''), v_profile.email),
      'approver_profile_id', new.approver_id
    )
  );

  insert into public.notification_events (
    event_type, source_table, source_id, source_folio, recipient_type,
    recipient_profile_id, recipient_email, recipient_role, channel, priority,
    subject, payload, idempotency_key, status, last_error, next_attempt_at
  ) values (
    'payment_request.created', 'payment_requests', new.id, new.request_number,
    'administrador_sistema',
    case when v_profile.id is not null then v_profile.id else null end,
    case when v_status = 'pending' then nullif(btrim(v_profile.email), '') else null end,
    v_role_name, 'email', 'normal',
    'Nueva solicitud de pago: ' || coalesce(new.request_number, new.id::text),
    v_payload,
    'payment_request.created:' || new.id::text || ':approver',
    v_status, v_last_error,
    case when v_status = 'pending' then now() else null end
  )
  on conflict (idempotency_key) do nothing;

  return new;
exception
  when others then
    insert into public.notification_events (
      event_type, source_table, source_id, source_folio, recipient_type,
      channel, priority, subject, payload, idempotency_key, status, last_error
    ) values (
      'payment_request.created', 'payment_requests', new.id, new.request_number,
      'administrador_sistema', 'email', 'normal',
      'Nueva solicitud de pago: ' || coalesce(new.request_number, new.id::text),
      jsonb_build_object('folio', new.request_number, 'path', '/solicitudes.html'),
      'payment_request.created:' || new.id::text || ':enqueue-error',
      'dead_letter', 'created_notification_enqueue_failed'
    )
    on conflict (idempotency_key) do nothing;
    return new;
end;
$function$
